import os
import re
from pymilvus import MilvusClient
from sentence_transformers import SentenceTransformer
import markdown

def get_markdown_content(file_path):
    """Read and return markdown content as plain text"""
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()
    
    # Convert HTML generated by markdown to plain text
    # For simplicity, we just remove HTML tags
    text = re.sub('<[^<]+?>', '', markdown.markdown(content))
    return text

def chunk_text(text, chunk_size=1000, overlap=200):
    """Split text into chunks with overlap"""
    words = text.split()
    chunks = []
    for i in range(0, len(words), chunk_size - overlap):
        chunk = ' '.join(words[i:i + chunk_size])
        chunks.append(chunk)
        if i + chunk_size >= len(words):
            break
    return chunks

def create_milvus_collection(client, collection_name, dimension):
    """Create a Milvus collection if it doesn't exist"""
    # Check if collection exists
    collections = client.list_collections()
    if collection_name in collections:
        return
    
    # Create the collection with the new client approach
    client.create_collection(
        collection_name=collection_name,
        dimension=dimension
    )

def generate_and_store_embeddings():
    """Main function to process markdown files and store embeddings in Milvus"""
    
    # Initialize Milvus client
    client = MilvusClient("./milvus_demo.db")
    
    # Initialize the sentence transformer model
    model = SentenceTransformer('all-MiniLM-L6-v2')  # 384 dimensions
    embedding_dim = 384
    
    # Create the collection if it doesn't exist
    collection_name = "test_collection"
    create_milvus_collection(client, collection_name, embedding_dim)
    
    # Get LIVRE markdown file
    md_file = "md_programs/livre-2024/livre-2024.md"
    
    # Process markdown file
    print(f"Processing {md_file}...")
    
    # Get content of the markdown file
    content = get_markdown_content(md_file)
    
    # Split content into chunks for better embedding
    chunks = chunk_text(content)
    
    # Prepare data for insertion
    data = []
    
    for i, chunk in enumerate(chunks):
        # Generate embedding for chunk
        embedding = model.encode(chunk).tolist()
        
        # Create data entry with simple sequential integer ID
        data.append({
            "id": i + 1,  # Simple sequential ID starting from 1
            "file_name": os.path.basename(md_file),
            "content": chunk,
            "vector": embedding
        })
    
    # Insert data into Milvus if we have any
    if data:
        print(f"Inserting {len(data)} embeddings into Milvus...")
        result = client.insert(
            collection_name=collection_name,
            data=data
        )
        print(f"Embeddings successfully stored in Milvus! Inserted: {result}")
    else:
        print("No markdown files found to process.")

def search_embeddings(query_text, top_k=5):
    """Search for similar content based on a query text"""
    
    # Initialize Milvus client and model (same as in generate_and_store_embeddings)
    client = MilvusClient("./milvus_demo.db")
    model = SentenceTransformer('all-MiniLM-L6-v2')
    collection_name = "test_collection"
    
    # Generate embedding for the query text
    query_embedding = model.encode(query_text).tolist()
    
    results = client.search(
        collection_name=collection_name,
        data=[query_embedding],
        limit=top_k,
        output_fields=["file_name", "content"]
    )
    
    return results
